  "knowledge": "Closet Indexer",
  "description": "A fund that is marketed as an active fund and charges higher fees, but its portfolio holdings and performance closely track a benchmark index.",
  "definition": "A fund is identified as a Closet Indexer if it is a 'Market-Tracking Fund' but has a positive 'Relative Expense Ratio'."
}

{
  "id": 11,
  "knowledge": "Market-Tracking Fund",
  "description": "A fund whose performance is highly correlated with its market benchmark.",
  "definition": "A fund is considered a Market-Tracking Fund if its 3-year R-squared value is greater than 90, indicating a strong correlation with its benchmark."
}

{
  "id": 86,
  "knowledge": "Wasted Fee Amount",
  "description": "The total dollar amount of fees paid by investors in a Closet Indexer fund that are in excess of the benchmark's expense ratio.",
  "definition": "WFA = (\text{Net Expense Ratio} - \text{Benchmark Expense Ratio}) \times \text{Net Worth}"
}
